CREATE OR REPLACE FUNCTION ECAMS.CMM0036_EXE
(SYSCD IN VARCHAR2,
 RSRCCD IN VARCHAR2
)
return VARCHAR2
IS
 SV_EXENAME VARCHAR2(4000);

CURSOR  Conf1 IS
    SELECT  distinct
            CR_SYSCD
          , CR_RSRCCD
          , SUBSTR(CR_RSRCNAME, INSTR(CR_RSRCNAME, '.', -1)) || ',' AS EXTNAME
      FROM  CMR0020
     WHERE  CR_SYSCD  = SYSCD
       AND  CR_RSRCCD = RSRCCD
       AND  INSTR(CR_RSRCNAME, '.') > 0
       AND  CR_CLSDATE IS NULL;


Begin
    SV_EXENAME   := '';

    For EXENAME In Conf1  Loop
        SV_EXENAME := SV_EXENAME || EXENAME.EXTNAME;
    End Loop;

    RETURN SV_EXENAME;

End cmm0036_EXE;